DELIMITER $$
--
-- Procedure
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cleanup_old_plates` (IN `days_old` INT)   BEGIN
    DELETE FROM plates
    WHERE DATE(date_detected) < DATE_SUB(CURDATE(), INTERVAL days_old DAY);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_plates_report` (IN `start_date` DATE, IN `end_date` DATE)   BEGIN
    SELECT 
        DATE(p.date_detected) as data,
        COUNT(*) as totale,
        SUM(CASE WHEN p.is_manual = TRUE THEN 1 ELSE 0 END) as manuali,
        SUM(CASE WHEN p.is_manual = FALSE THEN 1 ELSE 0 END) as rilevate
    FROM plates p
    WHERE DATE(p.date_detected) BETWEEN start_date AND end_date
    GROUP BY DATE(p.date_detected)
    ORDER BY data DESC;
END$$

DELIMITER ;

