DELIMITER $$
CREATE TRIGGER `tr_audit_plates` AFTER UPDATE ON `plates` FOR EACH ROW BEGIN
    VALUES ('UPDATE', 'plates', NEW.id, CONCAT('plate:', OLD.plate_number), CONCAT('plate:', NEW.plate_number));
END
$$
